INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('1480a4ce-720b-df0d-78fa-800dfe757874', 'Orient Bambino 38mm Small Seconds Automatic', 'orient-bambino-38mm-small-seconds-automatic', 'Orient Bambino 38mm — nafis ixcham o''lchamli vintage uslubidagi yapon durdonasi. 38mm ixcham korpus, pastki soat 6 dagi alohida soniya siferblati (Small Seconds), klassik Rim raqamlari, ko''k po''lat strelkalar, soat 3 da sana ko''rsatkichi va qora tabiiy charm tasma. 2 yil rasmiy kafolat bilan.', 3485000, 3950000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 5, 'ORT-BAMBINO-38MM', 5, 6, '/products/orient_bambino_38mm_small_seconds.png', true, false, true, '{"Korpus o''lchami":"38 mm (Ixcham klassik o''lcham)","Korpus materiali":"Zanglamas po''lat 316L","Mexanizm":"Orient Cal. F6222 Avtomatik (Yaponiya)","Shisha turi":"Gumbazsimon mineral kristall","Tasma":"Tabiiy qora charm (Alligator naqshli)","Funksiyalar":"Small Seconds (Alohida soniya), Sana","Suvga chidamlilik":"30 metr / 3 BAR","Kafolat":"2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
