INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('97348513-27f3-d54b-2196-dd89ecbcffd9', 'Orient Bambino 38mm Small Seconds Black Dial Automatic', 'orient-bambino-38mm-small-seconds-black-dial', 'Orient Bambino 38mm Black Dial — hashamatli qora siferblatli ixcham vintage uslubdagi yapon soati. 38mm ixcham korpus, soat 6 da nur taratuvchi alohida soniya sub-diali (Small Seconds), oq Rim raqamlari, soat 3 da sana darchasi va qora tabiiy charm tasma. 2 yil rasmiy kafolat bilan.', 3485000, 3950000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 5, 'ORT-BAMBINO-38-BLK', 5, 5, '/products/orient_bambino_38mm_small_seconds_black.png', true, false, true, '{"Korpus o''lchami":"38 mm (Ixcham klassik o''lcham)","Korpus materiali":"Zanglamas po''lat 316L","Mexanizm":"Orient Cal. F6222 Avtomatik (Yaponiya)","Shisha turi":"Gumbazsimon mineral kristall","Tasma":"Tabiiy qora charm (Alligator naqshli)","Funksiyalar":"Small Seconds (Alohida soniya), Sana","Suvga chidamlilik":"30 metr / 3 BAR","Kafolat":"2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
