INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('f57d42aa-fa92-dc0b-9afe-ac178ecb430f', 'Casio Edifice Automatic Sapphire 39mm', 'casio-edifice-automatic-sapphire-39mm', 'Original Casio Edifice — Yaponiyaning afsonaviy brendidan o''zi buraluvchi avtomatik mexanik soat. Qirilishga o''ta chidamli sapfir kristall shisha (Sapphire Crystal), 10 ATM (100 metr) suvga chidamlilik va ixcham 39 mm po''lat korpus. Yashil va to''q ko''k siferblat uyg''unligi, sana darchasi. To''plamda: original quti, hujjatlar va kafolat taloni. Narxi: $350.', 4480000, 5100000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Casio', 4, 'CAS-EDIFICE-AUTO-39', 5, 7, '/products/casio_edifice_automatic_39mm.png', true, false, true, '{"Korpus o''lchami":"39 mm","Korpus va tasma":"Zanglamas po''lat 316L (Solid Stainless Steel)","Mexanizm":"Yapon avtomatik mexanik (Self-winding)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Suvga chidamlilik":"10 ATM / 100 metr","Komplektatsiya":"Original quti, hujjatlar, xalqaro kafolat kartasi","Kafolat":"Mexanizmiga 1 yil rasmiy kafolat","Valyuta narxi":"$350"}'::jsonb) ON CONFLICT (id) DO NOTHING;
