INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('2e7a6fa6-c5a2-234a-de32-9e6782f347ec', 'Casio Edifice Solar Powered Sapphire Chronograph', 'casio-edifice-solar-powered-sapphire-chronograph', 'Original Casio Edifice Solar Powered — quyosh energiyasida ishlovchi akkumulyatorli yuqori aniqlikdagi yapon xronografi. Qirilishga chidamli sapfir kristall shisha (Sapphire Crystal), 10 ATM (100 metr) suvga chidamlilik. Akkumulyator quvvati indikatori (High/Mid/Low), sekundomer (xronograf), 24 soatlik ko''rsatkich, sana darchasi va qora tabiiy charm tasma. Original quti, hujjatlar va 2 yil rasmiy kafolat bilan.', 3050000, 3500000, 13, '84d75ece-80cd-79e1-e6d8-058603151218', 'Casio', 5, 'CAS-EDIFICE-SOLAR-CHRONO', 5, 8, '/products/casio_edifice_solar_sapphire.png', true, false, true, '{"Korpus o''lchami":"44 mm","Korpus materiali":"Qora ion qoplamali zanglamas po''lat 316L (Black IP)","Mexanizm":"Casio Solar-Powered (Quyosh energiyali kvars)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Tasma":"Oq chokli tabiiy qora charm tasma","Funksiyalar":"Xronograf sekundomer, Quvvat darajasi (H/M/L), 24-soatlik, Sana","Suvga chidamlilik":"10 ATM / 100 metr","Komplektatsiya":"Original Edifice qutisi, hujjatlar, xalqaro kafolat kartasi","Kafolat":"Mexanizmiga 2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
