INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('fe761d27-dc68-83cc-7752-c18c89710ac7', 'Casio Edifice Slim Octagonal Solar Sapphire Chronograph', 'casio-edifice-slim-octagonal-solar-sapphire-chronograph', 'Original Casio Edifice — nufuzli sakkizburchak (Octagonal sport-klassik) bezel va nozik korpusli quyosh energiyasida ishlovchi yapon xronografi. Qirilmaydigan sapfir kristall shisha (Sapphire Crystal), to''liq zanglamas po''lat braslet va korpus, 10 ATM (100 metr) suvga chidamlilik. Akkumulyator quvvati ko''rsatkichi (High/Mid/Low), sekundomer, sana darchasi. Komplektda: original quti, hujjatlar va 2 yil rasmiy kafolat bilan.', 2750000, 3200000, 14, '84d75ece-80cd-79e1-e6d8-058603151218', 'Casio', 6, 'CAS-EDIFICE-OCT-SOLAR', 5, 9, '/products/casio_edifice_octagonal_solar_sapphire.png', true, false, true, '{"Korpus dizayni":"44 mm, Sakkizburchakli (Octagonal) nufuzli dizayn","Korpus va braslet":"Zanglamas po''lat 316L (Solid Stainless Steel)","Mexanizm":"Casio Solar-Powered (Quyosh energiyali kvars)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Funksiyalar":"Xronograf sekundomer, Quvvat darajasi (H/M/L), Sana","Suvga chidamlilik":"10 ATM / 100 metr","Komplektatsiya":"Original Edifice qutisi, hujjatlar, xalqaro kafolat kartasi","Kafolat":"Mexanizmiga 2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
